// F60 Utskriftsstil: varje fristående sida i public/ (utom index, 404 och nyhetsbrev) har exakt ett
// utskriftsblock i <style> i <head>, blocken är lika på alla sidor, blocket hämtar inget, döljer inte
// AI-märkningen och har inga href="…"-citat. Ingen delad utskriftsfil. Självprov på trasiga varianter.
// AI-skapat (B-051). Generated by AI, Directed by MS.
const fs = require('fs');
const path = require('path');

const pub = 'public';
const START = '/* F60 utskrift start';
const SLUT = '/* F60 utskrift slut */';
const SLUTTEXT = 'Utskrift från luminusloom.net. Allt innehåll är AI-skapat.';
const RATSIDOR = ['besok-vreta.html', 'grenar.html', 'marknad.html', 'nytt.html', 'sa-marker-vi-ai.html', 'sidkarta.html', 'tillganglighet.html'];

// Plockar ut blocket ur en sida; null om det saknas, finns flera gånger eller ligger utanför <style> i <head>.
function block(html) {
  const forsta = html.indexOf(START);
  if (forsta < 0 || html.indexOf(START, forsta + 1) >= 0) return null;
  const slut = html.indexOf(SLUT, forsta);
  if (slut < 0) return null;
  const head = html.slice(0, html.indexOf('</head>'));
  const styleStart = head.lastIndexOf('<style', forsta);
  const styleSlut = head.indexOf('</style>', forsta);
  if (styleStart < 0 || styleSlut < 0 || slut > styleSlut) return null;
  return html.slice(forsta, slut + SLUT.length).split('\n').map((r) => r.trim()).join('\n');
}

function kontrolleraBlock(b) {
  const utan = b.replace(/\/\*[\s\S]*?\*\//g, '');
  return {
    innehall: b.includes('@media print') && /\.hoppa \{ display: none/.test(b) && b.includes("a[href^='/']::after") &&
      b.includes("a[href^='http']::after") && b.includes('attr(href)') && b.includes('background: #fff') &&
      b.includes('color: #000') && b.includes(SLUTTEXT),
    ingetHamtas: !/url\(/i.test(utan) && !/@import/i.test(utan) && !/https?:/i.test(utan) && !utan.includes('//'),
    aiSyns: !/(\.etikett|\.ai|header|footer)[^{}]*\{[^}]*display:\s*none/i.test(utan) && !/visibility:\s*hidden/i.test(utan),
    ingaHrefCitat: !b.includes('href="') && !b.includes('src="'),
  };
}

function kontrolleraSidor(sidor) {
  const fel = {};
  const blocken = {};
  for (const [namn, html] of Object.entries(sidor)) {
    const b = block(html);
    if (b === null) (fel.allaSidorHarBlocket ||= []).push(namn);
    else blocken[namn] = b;
  }
  const krav = { allaSidorHarBlocket: !fel.allaSidorHarBlocket && Object.keys(sidor).length >= 7 };
  krav.ratSidor = RATSIDOR.every((s) => s in sidor);
  const unika = new Set(Object.values(blocken));
  krav.sammaBlock = unika.size === 1 && Object.keys(blocken).length === Object.keys(sidor).length;
  if (!krav.sammaBlock) fel.sammaBlock = Object.keys(sidor);
  const forst = Object.values(blocken)[0] || '';
  Object.assign(krav, kontrolleraBlock(forst));
  for (const k of ['innehall', 'ingetHamtas', 'aiSyns', 'ingaHrefCitat']) {
    for (const [namn, b] of Object.entries(blocken)) if (!kontrolleraBlock(b)[k]) { krav[k] = false; (fel[k] ||= []).push(namn); }
  }
  return { krav, fel };
}

const sidnamn = fs.readdirSync(pub).filter((f) => f.endsWith('.html') && f !== 'index.html' && f !== '404.html' && !/^nyhetsbrev/.test(f)).sort();
const sidor = Object.fromEntries(sidnamn.map((f) => [f, fs.readFileSync(path.join(pub, f), 'utf8')]));
const { krav, fel } = kontrolleraSidor(sidor);

// 8. Ingen delad utskriftsfil.
const allaHtml = fs.readdirSync(pub).filter((f) => f.endsWith('.html')).map((f) => fs.readFileSync(path.join(pub, f), 'utf8'));
krav.ingenNyFil = !fs.existsSync(path.join(pub, 'css', 'utskrift.css')) && !allaHtml.some((h) => /<link[^>]*utskrift/i.test(h));

// 9. Självprov.
const gron = (k) => Object.values(k).every(Boolean);
const m = sidor['marknad.html'] || '';
const ersatt = (html, a, b) => { const r = html.replace(a, b); return r === html ? null : r; };
const varianter = [
  ersatt(m, '@media print', '@media screen'),
  ersatt(m, '.hoppa { display: none !important; }', ''),
  ersatt(m, 'body { font-size: 11pt;', 'body { background: url(x.png); font-size: 11pt;'),
  ersatt(m, '.etikett, .ai { border: 1px solid #000 !important; }', '.etikett { display: none; }'),
  ersatt(m, /  \/\* F60 utskrift start[\s\S]*?\/\* F60 utskrift slut \*\/\n/, ''),
  ersatt(m, '</style>', (block(m) || 'x') + '\n</style>'),
];
krav.testetFangar = m !== '' && gron(kontrolleraSidor(sidor).krav) &&
  varianter.every((v) => v !== null && !gron(kontrolleraSidor({ ...sidor, 'marknad.html': v }).krav));

const ok = gron(krav);
if (!ok) console.error('Röda: ' + Object.keys(krav).filter((k) => !krav[k]).join(', ') +
  (Object.keys(fel).length ? ' – ' + Object.entries(fel).map(([k, v]) => `${k}: ${v.join(', ')}`).join('; ') : ''));
console.log(JSON.stringify({ ...krav, sidor: sidnamn.length, ok }));
process.exit(ok ? 0 : 1);
